# pass.sh port host passname stills(true/false) a b
p=$1; h=$2; pn=$3; st=$4; a=$5; b=$6
ssh -p $p root@$h "tar xf - -C /workspace/unreal/src" < /tmp/src.tar
ssh -p $p root@$h "tar xf - -C /workspace/unreal/packs" < /tmp/gear.tar
ssh -p $p root@$h "R=/workspace/unreal; cd \$R; for s in final real1 warm $pn; do tmux kill-session -t \$s 2>/dev/null; done; for q in \$(pgrep -u ue UnrealEditor); do kill \$q; done; [ -f packs/shrubs/bracken_cured.glb ] && mv packs/shrubs/bracken_cured.glb packs/bracken_cured.glb.off; rm -rf proj/Content/Pack/bracken_cured; D=\$R/out/$pn; rm -rf \$D; mkdir -p \$D; cd src && python3 gen.py \$R/assets > \$D/gen.log 2>&1; tail -2 \$D/gen.log; cd \$R; echo '{\"build\":true,\"reimport\":true,\"out\":\"'\$D'\",\"stills\":$st,\"walk\":true,\"res\":[1920,1080],\"temporal\":8,\"walk_temporal\":1,\"walk_res\":[1920,1080],\"walk_range\":[$a,$b],\"skip_packs\":[\"ponderosa_pine\",\"grand_fir\",\"western_hemlock\",\"riparian_\"]}' > run.json; python3 -c 'import json;print(json.load(open(\"run.json\"))[\"walk_range\"])'; chown -R ue:ue proj out; chmod -R a+rX src assets run.json real packs; tmux new -d -s $pn \"UE_TIMEOUT=2400 bash src/run_ue.sh; python3 src/post.py \$D > \$D/post.log 2>&1\"; echo LAUNCHED_$h"
